// Kartu Kegawatdaruratan Olahraga (v0.2) — alat bantu ingat, bukan pengganti pelatihan BLS/ACLS.
// Dosis obat hanya bila tertulis eksplisit di pedoman yang dirujuk (keputusan 21 Nov), dihitung dari BB dengan batas maksimal.
const L = (id, en) => ({ id, en });
const fmt = (v, d, lg = 'id') => Number(v).toLocaleString(lg === 'id' ? 'id-ID' : 'en-GB', { minimumFractionDigits: d, maximumFractionDigits: d });

